<template>
  <div>
    <v-data-table
      v-model="gridData"
      :headers="headers"
      :items="gridData"
      item-value="id"
      class="elevation-1"
      @paste="handlePaste"
    >
    
    </v-data-table>
    <v-btn @click="exportData">Add Header Data</v-btn>
</div>
</template>

<script>
import { ref } from 'vue';
import { addProjectRec } from '../utils/contactUtils'; // Import the mutation function

export default {
  name: 'PasteGrid',
  setup() {
    // Define the headers based on the new structure
    const headers = [
      { text: 'No', value: 'no' },
      { text: 'Project Name', value: 'projectName' },
      { text: 'Project Type', value: 'projectType' },
      { text: 'Location', value: 'location' },
      { text: 'EUM PIC Name', value: 'eumPicName' },
      { text: 'EUM PIC Contact', value: 'eumPicContact' },
      { text: 'Branch', value: 'branch' },
      { text: 'Agent Comm (%)', value: 'agentComm' },
      { text: 'Advance Comm (%)', value: 'advanceComm' },
    ];

    const gridData = ref([]); // Holds grid data
    const exportedData = ref([]); // Will hold the exported array data

    function splitContactInfo(contactInfo) {
      
  // If contactInfo is undefined, set both name and phoneNumber to empty strings
  if (!contactInfo) {
    return { name: '', phoneNumber: '' };
  }

  // If no "\r\n", assign the entire contactInfo to name, and phoneNumber is an empty string
  if (!contactInfo.includes('\r\n')) {
    return { name: contactInfo, phoneNumber: '' };
  }

  // If "\r\n" is found, split into name and phoneNumber
  const [name, phoneNumber = ''] = contactInfo.split('\r\n');
  return { name, phoneNumber };
}
  

    // Function to handle pasted data
    const handlePaste = (event) => {
      const clipboardData = event.clipboardData || window.clipboardData;
      let pastedText = clipboardData.getData('text/plain');

    
pastedText = pastedText.replace("\tAdmin\r\n","\tAdmin\t") ;
     
// let formattedText = pastedText.replaceAll('\t', '//t');
// formattedText = formattedText.replaceAll('\r', '//r');
// formattedText = formattedText.replaceAll('\n', '//n');
// alert(formattedText);

      // Replace tabs and newlines with markers, then split into rows
      const rows = pastedText.trim().split('\t\r\n').filter((row) => row.trim() !== '');

      // Process each row and map to the correct columns
      const parsedData = rows.map((row) => {
        const columns = row.split('\t'); // Assuming tab or comma-separated values

        return {
          company: "EUM",
          no: (columns[0] ? columns[0].toString().padStart(3, '0') : ''),
          projectName: columns[1] || '',
          projectType: columns[2] || '',
          location: columns[3] || '',
          eumPicName: splitContactInfo(columns[4]).name,
          eumPicContact: splitContactInfo(columns[4]).phoneNumber,
          branch: columns[5] || '',
          agentComm: columns[6] || '', // Convert agent comm to number
          advanceComm: columns[7] || '', // Convert advance comm to number
        };
      });

      // Update grid data with parsed data
      gridData.value = [...gridData.value, ...parsedData];
      console.log(...parsedData);
    };

    // Function to add a new row
  

    // Function to export data to Strapi
    const exportData = async () => {
      try {
        for (const project of gridData.value) {
          // Call the mutation for each project
          await addProjectRec(project);
        }
        exportedData.value = [...gridData.value]; // Copy grid data to exported array
        alert('Data successfully exported to Strapi!');
      } catch (error) {
        console.error('Error exporting data to Strapi:', error);
        alert('Failed to export data.');
      }
    };

    return {
      headers,
      gridData,
      exportedData,
      handlePaste,
   
      exportData,
    };
  },
};
</script>

<style scoped>
.elevation-1 {
  min-height: 300px;
}
</style>
