<template>
  <v-container>
    <v-toolbar color="primary" dark>
      <v-toolbar-title>part 1</v-toolbar-title>
    </v-toolbar>



    <v-data-table v-model="gridData" :headers="headers" :items="gridData" item-value="id" class="elevation-1"
      @paste="handlePaste">

      <template v-slot:no-data>
        <v-btn @click="updateRow">Update Header - Part 1</v-btn>
        <h1>{{projectId}}</h1>
      </template>
    </v-data-table>



    <v-progress-linear v-if="loading" indeterminate color="primary"></v-progress-linear>



    <!-- Dialog for PasteProjectDetail -->
    <v-dialog v-model="dialog" max-width="800px">
      <v-card>
        <v-card-title>
          <span class="headline">Paste Project Header - Part 1</span>
        </v-card-title>
        <v-card-text>
   <h1>{{projectId}}</h1>

          <v-text-field v-model="newProject.branch" label="Branch" required></v-text-field>

          <v-text-field v-model="newProject.projectName" label="Project Name" required></v-text-field>
          <v-text-field v-model="newProject.projectType" label="Project Type" required></v-text-field>

          <v-text-field v-model="newProject.eumPicName" label="EUM PIC Name" required></v-text-field>

          <v-text-field v-model="newProject.eumPicContact" label="EUM PIC Contact No" 
            required></v-text-field>


       

          <v-text-field v-model="newProject.contractStartDate" label="Contract Start Date" 
            required></v-text-field>


          <v-text-field v-model="newProject.contractExpiryDate" label="Contract End Date" 
            required></v-text-field>

          <v-text-field v-model="newProject.rebate" label="Rebate"  required></v-text-field>

        
          <v-checkbox v-model="newProject.status" label="Active"></v-checkbox>

          <v-text-field v-model="newProject.agentComm" label="Agent Comm"  required></v-text-field>
          <v-text-field v-model="newProject.advanceComm" label="Advance Comm"  required></v-text-field>

          <v-text-field v-model="newProject.location" label="Location" required></v-text-field>

          
              </v-card-text>
        <v-card-actions>
          <v-btn color="primary" @click="submitProject">Submit</v-btn>
          <v-btn @click="closeDialog">Close</v-btn>
        </v-card-actions>
      </v-card>
      <v-btn @click="updateRow">Update Header Data</v-btn>

    </v-dialog>
    
     
  </v-container>
</template>

<script>
import { ref } from 'vue';
import { updateProjectRecPart1 } from '../utils/contactUtils'; // Import the mutation function

export default {
  name: 'ProjectListing',
  components: {

  },
  props: {
    projectId: {
      type: String,
      default: '', 
      required: true,
    },
  },
  setup(props) {
    const gridData = ref([]); // Holds grid data
    const headers = [
      { text: 'title', title: "title", value: 'title' },
      { text: 'description', title: "description", value: 'description' },

    ];

    const updateRow = async () => {
  try {
    const newLayout = {
      
      branch: newProject.value.branch,
      projectName: newProject.value.projectName,
      projectType: newProject.value.projectType,
      eumPicName: newProject.value.eumPicName,
      eumPicContact: newProject.value.eumPicContact,
      contractStartDate: newProject.value.contractStartDate,
      contractExpiryDate: newProject.value.contractExpiryDate,
      rebate: newProject.value.rebate,
      status: newProject.value.status,
      active: newProject.value.active,
      agentComm: newProject.value.agentComm,
      advanceComm: newProject.value.advanceComm,
      location:newProject.value.location,
    };
    
    await updateProjectRecPart1(props.projectId, newLayout);
    
    alert('Data successfully exported to Strapi!');
  } catch (error) {
    console.error('Error exporting data to Strapi:', error);
    alert('Failed to export data.');
  }
};


    const loading = ref(false);
    const error = ref(null);
    const dialog = ref(false);
    const selectedProjectId = ref(null);

    const newProject = ref({
      branch: '',
      projectName: '',
      projectType: '',
      eumPicName: '',
      eumPicContact: '',
      contractStartDate: '',
      contractExpiryDate: '',
      rebate: '',
      status: '',
      agentComm:'',
      advanceComm:'',
      location:''
  
    });

      const handlePaste = (event) => {
      console.log("****1");
      const clipboardData = event.clipboardData || window.clipboardData;
      let pastedText = clipboardData.getData('text/plain');

      // Assuming tab-separated values for simplicity
      pastedText = pastedText.replaceAll("\t\r\n", "~");
      pastedText = pastedText.replaceAll("\r\n", "|");
      pastedText = pastedText.replaceAll("Rebate~Status", "Rebate~-|Status");
      pastedText = pastedText.replaceAll("EUM PIC Contact No~Contract", "EUM PIC Contact No~-|Contract");
      pastedText = pastedText.replaceAll("Contract Expiry Date~Rebate", `Contract Expiry Date~-|Rebate`);
      const rows = pastedText.trim().split('|').filter((row) => row.trim() !== '');

      const parsedData = rows.map((row) => {
        const columns = row.split('~');
        return {
          title: columns[0] || '',
          description: columns[1] || '',
        };
      });
      console.log("****2");
      parsedData.forEach((item) => {

  
   


if (item.title === 'Branch') newProject.value.branch = item.description;
if (item.title === 'Project Name') newProject.value.projectName = item.description;
if (item.title === 'Project Type') newProject.value.projectType = item.description;
if (item.title === 'EUM PIC Name') newProject.value.eumPicName = item.description;
if (item.title === 'EUM PIC Contact No') newProject.value.eumPicContact = item.description;
if (item.title === 'Contract Start Date') newProject.value.contractStartDate = item.description;
if (item.title === 'Contract Expiry Date') newProject.value.contractExpiryDate = item.description;
if (item.title === 'Rebate') newProject.value.rebate = item.description;
if (item.title === 'Status') newProject.value.status = item.description=="Active";


if (item.title === 'Agent Comm.') newProject.value.agentComm = item.description;
if (item.title === 'Advance Comm.') newProject.value.advanceComm = item.description;
if (item.title === 'Location') newProject.value.location = item.description;

     

      });
      gridData.value = [...gridData.value, ...parsedData];
      dialog.value = true;
    };



    const openDialog = (id) => {
      selectedProjectId.value = id;
      dialog.value = true;
    };

   

    const closeDialog = () => {
  console.log('Close button clicked');
  dialog.value = false;
  selectedProjectId.value = null;
  resetNewProject();
};

    const resetNewProject = () => {
      newProject.value = {
      branch: '',
      projectName: '',
      projectType: '',
      eumPicName: '',
      eumPicContact: '',
      contractStartDate: '',
      contractExpiryDate: '',
      rebate: '',
      status: '',
      agentComm:'',
      advanceComm:'',
      location:''
      };
    };

    const submitProject = () => {
      console.log('New Project Data:', newProject.value);
      closeDialog();
    };

    return {
      headers,
      loading,
      error,
      openDialog,
      closeDialog,
      dialog,
      selectedProjectId,
      newProject,
      submitProject,
      handlePaste,
      gridData,
      updateRow
    };
  },
};
</script>

<style scoped>
.elevation-1 {
  min-height: 300px;
}
</style>
